CREATE OR REPLACE FUNCTION security.data_quality_overview_impl(p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing'
 SET work_mem TO '128MB'
AS $function$
with params as (select nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'') country_code),
course_scope as materialized (
 select c.id,c.provider_id,c.stable_key,c.canonical_title,c.course_code,c.course_url,c.delivery_mode,c.study_level_id,c.primary_field_id,c.last_verified_at,c.publication_status,
        co.iso_alpha2::text country_code
 from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
 where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))
), course_reg as (select r.course_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.course_registrations r join course_scope c on c.id=r.course_id group by r.course_id),
course_geo as (select cc.course_id,count(*)::int n,bool_or(coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null) has_delivery from catalogue.course_campuses cc join course_scope c on c.id=cc.course_id group by cc.course_id),
course_tax as (select o.course_id,bool_or(lower(o.mapping_status) in ('review_required','ambiguous')) filter(where o.status='current') ambiguous,bool_or(lower(o.mapping_status)='rejected') filter(where o.status='current') rejected from catalogue.course_study_level_observations o join course_scope c on c.id=o.course_id group by o.course_id),
reg_fee as (select f.course_id,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0)::int positives from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
provider_fee as (select f.course_id,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0)::int positives,bool_or(lower(coalesce(f.status,''))='suppressed') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') suppressed,bool_or(lower(coalesce(f.status,''))='rejected') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') rejected from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
course_link as (select l.course_id,count(*) filter(where lower(coalesce(l.status,'active'))='active')::int n,bool_or(lower(coalesce(l.status,''))='suppressed') suppressed,bool_or(lower(coalesce(l.status,''))='rejected') rejected from catalogue.course_links l join course_scope c on c.id=l.course_id where l.link_type = 'official_course' group by l.course_id),
course_intake as (select i.course_id,count(*) filter(where lower(coalesce(i.status,'active'))='active')::int n,bool_or(lower(coalesce(i.status,''))='suppressed') suppressed,bool_or(lower(coalesce(i.status,''))='rejected') rejected from catalogue.course_intakes i join course_scope c on c.id=i.course_id group by i.course_id),
course_english as (select e.course_id,count(*) filter(where lower(coalesce(e.status,'active'))='active')::int n,bool_or(lower(coalesce(e.status,''))='suppressed') suppressed,bool_or(lower(coalesce(e.status,''))='rejected') rejected from catalogue.course_english_requirements e join course_scope c on c.id=e.course_id group by e.course_id),
sch_course as (select sc.course_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join course_scope c on c.id=sc.course_id where sc.course_id is not null group by sc.course_id),
sch_provider as (select sc.provider_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join (select distinct provider_id from course_scope) p on p.provider_id=sc.provider_id where sc.scope_type='provider' and sc.provider_id is not null group by sc.provider_id),
course_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join course_scope c on c.id=el.entity_id where el.entity_type='course' group by el.entity_id),
course_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join course_scope c on c.id=es.entity_id group by es.entity_id),
course_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join course_scope c on c.id=q.entity_id group by q.entity_id),
course_flags as materialized (
 select c.*,
  (c.stable_key is not null and btrim(c.stable_key)<>'' and c.canonical_title is not null and btrim(c.canonical_title)<>'' and c.course_code is not null and btrim(c.course_code)<>'' and c.provider_id is not null) identity_ok,
  coalesce(r.n,0) reg_n,coalesce(g.n,0) campus_n,(coalesce(g.has_delivery,false) or coalesce(nullif(btrim(c.delivery_mode),''),null) is not null) has_delivery,
  (c.study_level_id is not null and c.primary_field_id is not null) taxonomy_complete,coalesce(t.ambiguous,false) taxonomy_ambiguous,coalesce(t.rejected,false) taxonomy_rejected,
  coalesce(rf.n,0) reg_fee_n,coalesce(rf.values_n,0) reg_fee_values,coalesce(rf.zeros,0) reg_fee_zero,coalesce(rf.positives,0) reg_fee_positive,
  coalesce(pf.n,0) provider_fee_n,coalesce(pf.values_n,0) provider_fee_values,coalesce(pf.zeros,0) provider_fee_zero,coalesce(pf.positives,0) provider_fee_positive,coalesce(pf.suppressed,false) provider_fee_suppressed,coalesce(pf.rejected,false) provider_fee_rejected,
  (coalesce(nullif(btrim(c.course_url),''),null) is not null or coalesce(cl.n,0)>0) has_url,coalesce(cl.suppressed,false) url_suppressed,coalesce(cl.rejected,false) url_rejected,
  coalesce(ci.n,0) intake_n,coalesce(ci.suppressed,false) intake_suppressed,coalesce(ci.rejected,false) intake_rejected,
  coalesce(ce.n,0) english_n,coalesce(ce.suppressed,false) english_suppressed,coalesce(ce.rejected,false) english_rejected,
  coalesce(sc.inc,0)+coalesce(sp.inc,0) scholarship_inc,coalesce(sc.exc,0)+coalesce(sp.exc,0) scholarship_exc,
  coalesce(ev.n,0) evidence_n,(sd.course_id is not null) search_projected,
  coalesce(cp.n,0) channel_n,coalesce(cp.published,0) channel_published,coalesce(cp.rejected,0) channel_rejected,coalesce(cp.statuses,0) channel_statuses,
  coalesce(rv.domains,'{}'::text[]) review_domains
 from course_scope c left join course_reg r on r.course_id=c.id left join course_geo g on g.course_id=c.id left join course_tax t on t.course_id=c.id left join reg_fee rf on rf.course_id=c.id left join provider_fee pf on pf.course_id=c.id left join course_link cl on cl.course_id=c.id left join course_intake ci on ci.course_id=c.id left join course_english ce on ce.course_id=c.id left join sch_course sc on sc.course_id=c.id left join sch_provider sp on sp.provider_id=c.provider_id left join course_ev ev on ev.entity_id=c.id left join search.course_documents sd on sd.course_id=c.id left join course_pub cp on cp.entity_id=c.id left join course_rev rv on rv.entity_id=c.id
),
provider_scope as materialized (select p.id,p.stable_key,p.canonical_name,p.country_id,p.subdivision_id,p.primary_city,p.address_line1,p.last_verified_at,p.publication_status,co.iso_alpha2::text country_code from catalogue.providers p join ref.countries co on co.id=p.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
provider_reg as (select r.provider_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.provider_registrations r join provider_scope p on p.id=r.provider_id group by r.provider_id),
provider_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join provider_scope p on p.id=el.entity_id where el.entity_type='provider' group by el.entity_id),
provider_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join provider_scope p on p.id=es.entity_id group by es.entity_id),
provider_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join provider_scope p on p.id=q.entity_id group by q.entity_id),
provider_flags as materialized (select p.*,(p.stable_key is not null and btrim(p.stable_key)<>'' and p.canonical_name is not null and btrim(p.canonical_name)<>'' and p.country_id is not null) identity_ok,coalesce(r.n,0) reg_n,(p.subdivision_id is not null or coalesce(nullif(btrim(p.primary_city),''),null) is not null or coalesce(nullif(btrim(p.address_line1),''),null) is not null) geography_present,coalesce(e.n,0) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from provider_scope p left join provider_reg r on r.provider_id=p.id left join provider_ev e on e.entity_id=p.id left join provider_pub pb on pb.entity_id=p.id left join provider_rev rv on rv.entity_id=p.id),
campus_scope as materialized (select ca.id,ca.stable_key,ca.name,ca.provider_id,ca.country_id,ca.subdivision_id,ca.city,ca.address_line1,ca.latitude,ca.longitude,ca.evidence_id,ca.last_verified_at,ca.publication_status,co.iso_alpha2::text country_code from catalogue.campuses ca join ref.countries co on co.id=ca.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
campus_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join campus_scope c on c.id=el.entity_id where el.entity_type='campus' group by el.entity_id),
campus_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join campus_scope c on c.id=es.entity_id group by es.entity_id),
campus_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join campus_scope c on c.id=q.entity_id group by q.entity_id),
campus_flags as materialized (select c.*,(c.stable_key is not null and btrim(c.stable_key)<>'' and c.name is not null and btrim(c.name)<>'' and c.provider_id is not null and c.country_id is not null) identity_ok,(c.subdivision_id is not null or coalesce(nullif(btrim(c.city),''),null) is not null or coalesce(nullif(btrim(c.address_line1),''),null) is not null or (c.latitude is not null and c.longitude is not null)) geography_present,coalesce(e.n,case when c.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from campus_scope c left join campus_ev e on e.entity_id=c.id left join campus_pub pb on pb.entity_id=c.id left join campus_rev rv on rv.entity_id=c.id),
scholarship_scope as materialized (select s.id,s.stable_key,s.name,s.provider_id,s.description,s.source_url,s.evidence_id,s.publication_status,coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) country_code from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries pc on pc.id=p.country_id left join pipeline.sources src on src.id=s.source_id left join ref.countries sc on sc.id=src.country_id where ((((select country_code from params) is null) and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) in ('AU','NZ')) or coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text)=(select country_code from params))),
sch_scope as (select sc.scholarship_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc from scholarship.scopes sc join scholarship_scope s on s.id=sc.scholarship_id group by sc.scholarship_id),
sch_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join scholarship_scope s on s.id=el.entity_id where el.entity_type='scholarship' group by el.entity_id),
sch_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join scholarship_scope s on s.id=es.entity_id group by es.entity_id),
sch_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join scholarship_scope s on s.id=q.entity_id group by q.entity_id),
sch_flags as materialized (select s.*,(s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>'') identity_ok,(coalesce(nullif(btrim(s.description),''),null) is not null and coalesce(nullif(btrim(s.source_url),''),null) is not null and s.evidence_id is not null and (coalesce(ss.inc,0)>0 or s.provider_id is null)) semantic_present,coalesce(e.n,case when s.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from scholarship_scope s left join sch_scope ss on ss.scholarship_id=s.id left join sch_ev e on e.entity_id=s.id left join sch_pub pb on pb.entity_id=s.id left join sch_rev rv on rv.entity_id=s.id),
all_states as (
 select 'course'::text entity_type,v.domain,v.state from course_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(c.review_domains) then 'ambiguous' when c.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.campus_n>0 and c.has_delivery then 'present' when c.country_code='AU' and c.campus_n=0 then 'source_null' else 'not_yet_enriched' end),
  ('taxonomy',case when 'taxonomy'=any(c.review_domains) or c.taxonomy_ambiguous then 'ambiguous' when c.taxonomy_rejected then 'rejected' when c.taxonomy_complete then 'present' when c.country_code='AU' then 'source_null' else 'not_yet_enriched' end),
  ('regulatory_fee',case when 'regulatory_fee'=any(c.review_domains) then 'ambiguous' when c.country_code<>'AU' then 'not_applicable' when c.reg_fee_n=0 or c.reg_fee_values=0 then 'source_null' when c.reg_fee_positive>0 then 'present' when c.reg_fee_zero>0 then 'zero' else 'source_null' end),
  ('provider_current_fee',case when 'provider_current_fee'=any(c.review_domains) then 'ambiguous' when c.provider_fee_rejected then 'rejected' when c.provider_fee_suppressed and c.provider_fee_n=0 then 'suppressed' when c.provider_fee_n=0 then 'not_yet_enriched' when c.provider_fee_values=0 then 'source_null' when c.provider_fee_positive>0 then 'present' when c.provider_fee_zero>0 then 'zero' else 'source_null' end),
  ('course_url',case when 'course_url'=any(c.review_domains) then 'ambiguous' when c.url_rejected then 'rejected' when c.url_suppressed and not c.has_url then 'suppressed' when c.has_url then 'present' else 'not_yet_enriched' end),
  ('intake',case when 'intake'=any(c.review_domains) then 'ambiguous' when c.intake_rejected then 'rejected' when c.intake_suppressed and c.intake_n=0 then 'suppressed' when c.intake_n>0 then 'present' else 'not_yet_enriched' end),
  ('english_requirement',case when 'english_requirement'=any(c.review_domains) then 'ambiguous' when c.english_rejected then 'rejected' when c.english_suppressed and c.english_n=0 then 'suppressed' when c.english_n>0 then 'present' else 'not_yet_enriched' end),
  ('scholarship',case when 'scholarship'=any(c.review_domains) then 'ambiguous' when c.scholarship_inc>0 then 'present' when c.scholarship_exc>0 then 'not_applicable' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('search_admission',case when 'search_admission'=any(c.review_domains) then 'ambiguous' when c.search_projected then 'present' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'provider',v.domain,v.state from provider_flags p cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(p.review_domains) then 'ambiguous' when p.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(p.review_domains) then 'ambiguous' when p.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(p.review_domains) then 'ambiguous' when p.geography_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(p.review_domains) then 'ambiguous' when p.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(p.review_domains) then 'ambiguous' when p.last_verified_at is null or p.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(p.review_domains) then 'ambiguous' when p.channel_rejected>0 or lower(coalesce(p.publication_status,''))='rejected' then 'rejected' when p.channel_statuses>1 then 'ambiguous' when p.channel_published>0 or lower(coalesce(p.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'campus',v.domain,v.state from campus_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.geography_present then 'present' else 'source_null' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'scholarship',v.domain,v.state from sch_flags s cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(s.review_domains) then 'ambiguous' when s.identity_ok then 'present' else 'source_null' end),
  ('scholarship',case when 'scholarship'=any(s.review_domains) then 'ambiguous' when s.semantic_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(s.review_domains) then 'ambiguous' when s.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(s.review_domains) then 'ambiguous' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(s.review_domains) then 'ambiguous' when s.channel_rejected>0 or lower(coalesce(s.publication_status,''))='rejected' then 'rejected' when s.channel_statuses>1 then 'ambiguous' when s.channel_published>0 or lower(coalesce(s.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
), defs(domain,label,sort_order,definition,authority) as (values
 ('identity_completeness','Identity completeness',10,'Stable governed identity fields required to resolve the entity without title/name inference.','Layer 1 canonical identity'),('regulatory_completeness','Regulatory completeness',20,'Current authoritative registration/Layer 1 regulatory presence; country-specific authority is preserved.','CRICOS / NZQA Layer 1'),('geography_delivery','Geography / delivery',30,'Provider/Campus geography and Course delivery relationships remain distinct. AU CRICOS source-absent Course Locations are not synthesised.','Layer 1 location authority / later enrichment'),('taxonomy','Taxonomy',40,'Governed Study Level and Field mappings; ambiguous/rejected source mappings remain exceptions.','Governed reference taxonomy'),('regulatory_fee','Regulatory fee',50,'AU CRICOS registered total-course tuition only. NZ has no CRICOS-equivalent fee dimension in the accepted Layer 1 contract.','CRICOS regulatory source'),('provider_current_fee','Current Provider fee',60,'Current Provider-published fee observations remain separate from CRICOS registered total-course fees.','Layer 2 Provider first-party source'),('course_url','Course URL',70,'Official Course URL/link enrichment; absence before a successful enrichment is not treated as source-null.','Layer 2 Provider first-party source'),('intake','Intake',80,'Provider-current intake observations with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('english_requirement','English requirement',90,'Provider-current English entry requirements with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('scholarship','Scholarship',100,'Relational Scholarship applicability; no scholarship relationship is not treated as a canonical Course defect.','Layer 2 Scholarship sources'),('evidence','Evidence',110,'Presence of governed evidence lineage for the canonical/enrichment entity.','Evidence workspace / source snapshots'),('verification_freshness','Verification / freshness',120,'Explicit verification timestamps only; missing or older-than-180-day verification is stale. Scholarship verification is not inferred from updated_at.','Canonical verification semantics'),('search_admission','Search admission',130,'Presence in the governed Search projection; this does not imply enrichment admission or publication.','Search course-v2 projection'),('publication_readiness','Publication readiness',140,'Recorded canonical/channel publication progression; no channel state is not invented as published.','Canonical + publishing channel state')),
agg as (select entity_type,domain,count(*)::bigint scope_count,count(*) filter(where state<>'not_applicable')::bigint applicable_count,count(*) filter(where state in ('present','zero'))::bigint ready_count,count(*) filter(where state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))::bigint attention_count,jsonb_build_object('present',count(*) filter(where state='present'),'source_null',count(*) filter(where state='source_null'),'not_applicable',count(*) filter(where state='not_applicable'),'zero',count(*) filter(where state='zero'),'suppressed',count(*) filter(where state='suppressed'),'not_yet_enriched',count(*) filter(where state='not_yet_enriched'),'stale',count(*) filter(where state='stale'),'ambiguous',count(*) filter(where state='ambiguous'),'rejected',count(*) filter(where state='rejected')) states from all_states group by entity_type,domain),
metrics as (select a.*,d.label,d.sort_order,d.definition,d.authority,case when a.applicable_count=0 then null else round(a.ready_count*100.0/a.applicable_count,2) end readiness_pct from agg a join defs d using(domain))
select jsonb_build_object('scope',jsonb_build_object('country_code',(select country_code from params),'default_scope',case when (select country_code from params) is null then 'AU+NZ' else (select country_code from params) end,'as_of',now()),'policy',jsonb_build_object('composite_score','not_exposed','reason','Cross-domain equal weighting conflates regulatory authority, enrichment coverage, Search admission and publication state. Domain readiness is reported instead.','ready_states',jsonb_build_array('present','zero'),'excluded_from_denominator',jsonb_build_array('not_applicable')),'state_vocabulary',jsonb_build_array('present','source_null','not_applicable','zero','suppressed','not_yet_enriched','stale','ambiguous','rejected'),'metrics',coalesce((select jsonb_agg(jsonb_build_object('entity_type',entity_type,'domain',domain,'label',label,'scope_count',scope_count,'applicable_count',applicable_count,'ready_count',ready_count,'attention_count',attention_count,'readiness_pct',readiness_pct,'states',states,'definition',definition,'authority',authority) order by sort_order,entity_type) from metrics),'[]'::jsonb))
$function$
